import{_ as i,C as n,o as t,c,a7 as a,b as r,w as d,a as h,E as s,a8 as u}from"./chunks/framework.BCbKzsgW.js";const f=JSON.parse('{"title":"账号模型与生命周期","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/account-lifecycle.md","filePath":"development/common/authentication/account-lifecycle.md","lastUpdated":1793703140000}'),l={name:"development/common/authentication/account-lifecycle.md"};function p(E,e,_,b,g,m){const o=n("Mermaid");return t(),c("div",null,[e[1]||(e[1]=a('<h1 id="zhang-hao-mo-xing-yu-sheng-ming-zhou-qi" tabindex="-1">账号模型与生命周期 <a class="header-anchor" href="#zhang-hao-mo-xing-yu-sheng-ming-zhou-qi" aria-label="Permalink to &quot;账号模型与生命周期&quot;">​</a></h1><p>账号需要一个稳定的内部 ID。邮箱、手机号、第三方登录方式和企业归属都可能变化，把其中任何一项直接作为业务主键，会让换绑、合并与注销变成跨表迁移。</p><p>以下是业务建模建议，不是某个认证协议规定的数据库结构。</p><h2 id="fen-kai-bao-cun-zhang-haobiao-shi-yu-cheng-yuan-guan-xi" tabindex="-1">分开保存账号、标识与成员关系 <a class="header-anchor" href="#fen-kai-bao-cun-zhang-haobiao-shi-yu-cheng-yuan-guan-xi" aria-label="Permalink to &quot;分开保存账号、标识与成员关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实体</th><th>核心字段</th><th>约束</th></tr></thead><tbody><tr><td><code>users</code></td><td><code>id</code>、<code>status</code>、<code>security_version</code></td><td>ID 稳定，账号状态独立于凭据</td></tr><tr><td><code>login_identifiers</code></td><td><code>user_id</code>、<code>type</code>、<code>normalized_value</code>、<code>verified_at</code></td><td>按产品的全局或租户范围唯一</td></tr><tr><td><code>password_credentials</code></td><td><code>user_id</code>、<code>password_hash</code>、<code>changed_at</code></td><td>不保存明文或可逆密码</td></tr><tr><td><code>external_identities</code></td><td><code>user_id</code>、<code>issuer</code>、<code>subject</code></td><td>联合身份键唯一</td></tr><tr><td><code>authenticators</code></td><td><code>user_id</code>、<code>type</code>、<code>status</code>、认证器数据</td><td>一人可以拥有多个认证器</td></tr><tr><td><code>memberships</code></td><td><code>tenant_id</code>、<code>user_id</code>、<code>status</code></td><td>一人可以加入多个租户</td></tr><tr><td><code>sessions</code></td><td><code>user_id</code>、会话凭据摘要、时间、撤销状态</td><td>账号与设备会话分开管理</td></tr></tbody></table><p>OIDC 的主体键使用 <code>(issuer, subject)</code>，不要只保存昵称或邮箱；<code>sub</code> 的语义与约束见 <a href="https://openid.net/specs/openid-connect-core-1_0.html#IDToken" target="_blank" rel="noreferrer">OIDC Core §2</a>。同一个自然人在不同身份提供方、不同 pairwise subject 范围内可能对应不同标识，应用需要显式关联。</p><p>认证器数据必须按类型分开处理：密码存慢哈希，TOTP 秘钥需要受保护的可恢复存储，WebAuthn 保存公钥。把所有凭据统一塞进一个不加约束的 <code>secret</code> 字段，会隐藏完全不同的保护要求。</p><h2 id="biao-shi-gui-fan-hua-xu-yao-ye-wu-gui-ze" tabindex="-1">标识规范化需要业务规则 <a class="header-anchor" href="#biao-shi-gui-fan-hua-xu-yao-ye-wu-gui-ze" aria-label="Permalink to &quot;标识规范化需要业务规则&quot;">​</a></h2><p>邮箱的域名部分可以按既定规则规范化；不要擅自删除邮箱本地部分的点号或 <code>+tag</code>，这些行为并非所有邮件服务都相同。是否大小写折叠也应成为产品规则，在注册、查询、换绑与唯一索引中一致执行。</p><p>手机号需要国家或地区信息，使用可维护的号码解析库统一格式。号码合法、当前可接收验证码和长期归属某个人，是三个不同结论。号码回收后，依靠旧手机号自动恢复账号可能把资产交给新持有人。</p><p>登录标识的唯一性最终由数据库保证。先查“未占用”再插入只是用户体验优化，不能阻止两个并发注册同时成功。</p><h2 id="zhu-ce-yu-ji-huo" tabindex="-1">注册与激活 <a class="header-anchor" href="#zhu-ce-yu-ji-huo" aria-label="Permalink to &quot;注册与激活&quot;">​</a></h2><p>以下是一种可选的账号状态模型。图中的解除限制与撤回注销都需要满足产品策略，不能由一次普通登录自动触发。</p>',13)),(t(),r(u,null,{default:d(()=>[s(o,{id:"mermaid-130",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20pending%5B%22%E5%BE%85%E6%BF%80%E6%B4%BB%3Cbr%3Epending%22%5D%20--%3E%7C%22%E6%A0%87%E8%AF%86%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%22%7C%20active%5B%22%E5%8F%AF%E7%94%A8%3Cbr%3Eactive%22%5D%0A%20%20%20%20active%20--%3E%7C%22%E5%B0%81%E7%A6%81%E6%88%96%E9%99%90%E5%88%B6%22%7C%20suspended%5B%22%E5%B7%B2%E9%99%90%E5%88%B6%3Cbr%3Esuspended%22%5D%0A%20%20%20%20suspended%20--%3E%7C%22%E5%AE%A1%E6%A0%B8%E5%90%8E%E8%A7%A3%E9%99%A4%22%7C%20active%0A%20%20%20%20active%20--%3E%7C%22%E7%A1%AE%E8%AE%A4%E6%B3%A8%E9%94%80%22%7C%20deleting%5B%22%E7%AD%89%E5%BE%85%E6%B3%A8%E9%94%80%3Cbr%3Edeletion_pending%22%5D%0A%20%20%20%20deleting%20--%3E%7C%22%E6%9C%9F%E9%99%90%E5%86%85%E6%89%B9%E5%87%86%E6%92%A4%E5%9B%9E%22%7C%20active%0A%20%20%20%20deleting%20--%3E%7C%22%E5%AE%8C%E6%88%90%E8%B5%84%E4%BA%A7%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%A4%84%E7%90%86%22%7C%20deleted%5B%22%E5%B7%B2%E6%B3%A8%E9%94%80%3Cbr%3Edeleted%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>临时登录限流与账号状态分别记录，避免一次验证码失败把整个账号置为不可用。未验证的预注册请求可以到期清理，不必全部创建为正式账号。</p><p>注册事务至少处理以下边界：</p><ol><li>创建短期注册请求，绑定目标标识、用途和有效期。</li><li>完成邮箱或手机验证，原子消费验证凭据。</li><li>在事务内创建或激活账号、写入已验证标识，由唯一约束处理并发冲突。</li><li>提交成功后发送欢迎消息等非关键通知，通知失败不回滚已完成的注册。</li></ol><p>不应让未验证注册无限占用某个邮箱。可以使用短期预注册记录和清理策略，也可以在验证成功时才创建正式账号。公开返回信息与内部错误码分开，减少账号枚举，具体见<a href="./password.html">密码与恢复</a>。</p><h2 id="bang-dingdeng-lu-yu-he-bing-shi-san-zhong-cao-zuo" tabindex="-1">绑定、登录与合并是三种操作 <a class="header-anchor" href="#bang-dingdeng-lu-yu-he-bing-shi-san-zhong-cao-zuo" aria-label="Permalink to &quot;绑定、登录与合并是三种操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>已有证明</th><th>结果</th></tr></thead><tbody><tr><td>使用外部身份登录</td><td>该提供方的有效认证结果</td><td>找到已绑定的本地账号</td></tr><tr><td>给现有账号绑定身份</td><td>当前账号近期认证 + 新身份认证</td><td>新增一条外部身份关联</td></tr><tr><td>合并两个本地账号</td><td>对两个账号均有足够控制证明</td><td>按业务规则迁移或关联资产</td></tr></tbody></table><p>默认不因外部提供方返回同一邮箱而自动绑定已有账号。邮箱声明、提供方验证规则与本地账号控制权不完全等价；即使 <code>email_verified=true</code>，仍需符合本地信任与关联策略。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html#secure-federated-account-linking" target="_blank" rel="noreferrer">OWASP 的联合账号关联建议</a>要求对关联过程单独防护。</p><p>绑定事务需要唯一约束：同一外部身份不能同时属于两个用户。若已被其他用户绑定，返回受控冲突，不做“最后写入覆盖”。解绑最后一种可用登录方式前，应先建立并验证替代方式。</p><p>账号合并还要处理订阅、余额、订单归属、团队角色和审计历史。通常更适合单独的业务流程，而不是在登录回调中执行。原账号可保留不可登录的映射记录，避免历史外键被随意改写。</p><h2 id="huan-bang-yu-hui-fu" tabindex="-1">换绑与恢复 <a class="header-anchor" href="#huan-bang-yu-hui-fu" aria-label="Permalink to &quot;换绑与恢复&quot;">​</a></h2><p>已登录用户换绑邮箱时，既要证明能控制新邮箱，也要证明此次操作来自当前账号控制者。可组合近期密码或强认证、新邮箱验证、旧渠道通知；高风险账号需要延迟生效或人工复核。</p><p>所有换绑请求绑定 <code>user_id</code>、新标识、用途与安全版本。发起后密码被重置、账号被封禁或版本变化，原请求应失效，避免旧链接在账号恢复后继续改变控制权。</p><p>恢复过程详见<a href="./password.html">密码、验证码与账号恢复</a>，认证器丢失见<a href="./mfa-passkey.html">多因素认证与 Passkey</a>。</p><h2 id="qi-ye-cheng-yuan-chi-zhi-yu-zhang-hao-zhu-xiao" tabindex="-1">企业成员离职与账号注销 <a class="header-anchor" href="#qi-ye-cheng-yuan-chi-zhi-yu-zhang-hao-zhu-xiao" aria-label="Permalink to &quot;企业成员离职与账号注销&quot;">​</a></h2><p>离开某个企业通常只应禁用相应 <code>membership</code>，不应自动删除个人账号及其他企业成员关系。租户角色也不能保存在全局 <code>users.role</code> 中。</p><p>全局封禁需要拒绝新登录、撤销刷新资格，并让现有会话按确定的时限失效。删除成员则至少影响该租户内的访问、令牌刷新和后台任务；其他租户是否受影响取决于账号风险。</p><p>账号注销还涉及资产结清、数据保留与匿名化。产品应定义可撤销等待期、最终删除范围和标识复用规则。保留审计记录的必要性、期限与访问控制需由业务和适用规则确定，不能用“软删除”无限期保留所有个人数据。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>OpenID Foundation：<a href="https://openid.net/specs/openid-connect-core-1_0.html#IDToken" target="_blank" rel="noreferrer">OpenID Connect Core §2 — ID Token</a></li><li>OWASP：<a href="https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html#secure-federated-account-linking" target="_blank" rel="noreferrer">Secure Federated Account Linking</a></li></ul>',19))])}const y=i(l,[["render",p]]);export{f as __pageData,y as default};
